	(167, 62, 2, '아메데 등대섬 사진 보고 싶습니다. 다음 글 부탁드려요!', '175.112.34.21', 'ACTIVE', 0, '2026-04-21 13:00:00', '2026-04-21 13:00:00', NULL, 0, 0),
	(168, 62, 7, '인천 직항 언제 뜨나요? 노선 정보 궁금합니다.', '220.85.67.43', 'ACTIVE', 0, '2026-04-21 13:30:00', '2026-04-21 13:30:00', NULL, 0, 0),
	(169, 62, 9, '다음주에 아메데 사진만 모아서 포스팅 해볼게요!', '110.47.22.88', 'ACTIVE', 0, '2026-04-21 14:00:00', '2026-04-21 14:00:00', 167, 0, 0),
	(170, 62, 12, '에어칼린이 주기적으로 인천-누메아 띄웁니다. 특가 뜰 때 잡으세요.', '58.231.101.14', 'ACTIVE', 0, '2026-04-21 14:30:00', '2026-04-21 14:30:00', 168, 0, 0),
	(171, 26, 11, '아ㅋㅋ', '0:0:0:0:0:0:0:1', 'ACTIVE', 1, '2026-04-21 07:31:06', '2026-04-22 01:11:02', NULL, 1, 0),
