	(168, '0c6cd19f-2e18-45f2-a9f9-26d7685d3e12', 'SPOT', 26, 'name', '도쿄 디즈니랜드', '12992e6a22cd9b3a8de6fdfe33879e5c9069df2fd803d3fde61f9973aba51394', 'zh', '东京迪士尼乐园', 'google-cloud-translation-v2', '2026-04-16 07:41:44', '2026-04-16 07:41:44'),
